* assembly Octree routines for simple efficiency over C code* Quick'n'Dirty(tm)	mcopy	octreea.mac	case on* The octree data structureMAXDEPTH	gequ	7o_leaf	gequ	0o_level	gequ	2o_colorindex	gequ	4o_children	gequ	6o_colorcount	gequ	8o_bsum	gequ	12o_gsum	gequ	16o_rsum	gequ	20o_nextreduce	gequ	24o_next	gequ	28* 'i' is in X* 'a' is in A* if the specified bit (i) in 'a' is set, return 1, else return 0TESTBITa	start	ldy	#1	; assume the bit is set	pha	txa	asl	a	tax	pla	and	>bittbl,X	bne	byebye	ldy	#0byebye	tya               rts    	ENDquant	STARTres	equ	1maxsublevel	equ	3sum	equ	5	sub	(3:orig,4:tree),8	phb	phk	plb	;	ldy	#o_leafloop	lda	[tree]               beq	notleaf	ldy	#o_colorindex	lda	[tree],y	sta	res               bra	goawaynotleaf	lda	#MAXDEPTH	ldy	#o_level	sec	sbc	[tree],y	sta	maxsublevel		tax	lda	orig+2	; do red	and	#$FF	jsr	TESTBITa	asl	a	asl	a	sta	sum	ldx	maxsublevel	lda	orig+1	; do green	and	#$FF	jsr	TESTBITa	asl	a	ora	sum	sta	sum	ldx	maxsublevel	lda	orig	; do blue	and	#$FF	jsr	TESTBITa	ora	sum	asl	a	asl	a	; multiply by four	clc	adc	#o_next	tay	lda	[tree],y	tax	iny	iny	lda	[tree],y	sta	tree+2	stx	tree               bra	loopgoaway	plb	ret	2:res	ENDinserttree	STARTtree	equ	1branch	equ	5maxsublevel	equ	7	sub (4:weight,2:depth,3:rgb,4:treep),8loop	lda	[treep]	sta	tree	ldy	#2	lda	[treep],y	sta	tree+2	lda	tree	ora	tree+2	bne	is_alloced	               pei	(depth)	pei	(treep+2)	pei	(treep)	jsl	newandinit	lda	[treep]	; re-dereference the pointer	sta	tree	ldy	#2	lda	[treep],y	sta	tree+2is_alloced	anop; (*tree)->colorcount += weight;	ldy	#o_colorcount	lda	[tree],y	clc	adc	weight	sta	[tree],y	ldy	#o_colorcount+2	lda	[tree],y	adc	weight+2	sta	[tree],y; (*tree)->rgbsum.r += Ulong(rgb.r) * weight;	pei	(weight+2)	pei	(weight)	ldx	#0	lda	rgb+2	and	#$FF		jsl	~UMUL4	ldy	#o_rsum	pla	clc	adc	[tree],y	sta	[tree],y	ldy	#o_rsum+2	pla	adc	[tree],y	sta	[tree],y	pei	(weight+2)	pei	(weight)	ldx	#0	lda	rgb+1	and	#$FF		jsl	~UMUL4	ldy	#o_gsum	pla	clc	adc	[tree],y	sta	[tree],y	ldy	#o_gsum+2	pla	adc	[tree],y	sta	[tree],y	pei	(weight+2)	pei	(weight)	ldx	#0	lda	rgb	and	#$FF	jsl	~UMUL4	ldy	#o_bsum	pla	clc	adc	[tree],y	sta	[tree],y	ldy	#o_bsum+2	pla	adc	[tree],y	sta	[tree],y	lda	[tree]	; o_leaf	jne	goaway	; we're done	lda	depth	cmp	>leaflevel	jcs	goaway; * calculate the branch we need to follow	lda	#MAXDEPTH	sec	sbc	depth	sta	maxsublevel		tax	lda	rgb+2	; do red	and	#$FF	jsr	TESTBITa	asl	a	asl	a	sta	branch	ldx	maxsublevel	lda	rgb+1	; do green	and	#$FF	jsr	TESTBITa	asl	a	ora	branch	sta	branch	ldx	maxsublevel	lda	rgb	; do blue	and	#$FF	jsr	TESTBITa	ora	branch	asl	a	asl	a	; multiply by four	clc	adc	#o_next	tay	sty	branch	lda	[tree],y	iny	iny	ora	[tree],y	bne	doloopagain	ldy	#o_children	lda	[tree],y	inc	a	sta	[tree],y	cmp	#2	bne	doloopagain	pei	(tree+2)	pei	(tree)	pei	(depth)	jsl	makereduceabledoloopagain	inc	depth	lda	tree	clc	adc	branch	sta	treep	lda	tree+2	adc	#0	sta	treep+2	jmp	loopgoaway	ret	ENDnewandinit	STARTtree	equ	1	sub	(2:depth,4:treep),4               lda	>nodes	ora	>nodes+2	bne	nodes_alloced	ph4	#60*500	; nodes are 60 bytes, get 300 of 'em	jsl	malloc	sta	>nodes	txa	sta	>nodes+2	lda	#0		sta	>node_alloc_indnodes_alloced	anop	lda	>node_alloc_ind	cmp	#500	bne	gotit	pea	1	jsl	exitgotit	pea	0	pea	60	ldx	#0	lda	>node_alloc_ind	jsl	~UMUL4	pla	clc	adc	>nodes	sta	tree	sta	[treep]	pla	adc	>nodes+2	sta	tree+2	               ldy	#2	sta	[treep],y               lda	>node_alloc_ind	inc	a	sta	>node_alloc_ind	ldy	#o_colorindex	lda	#0lp	sta	[tree],y	iny	iny	cpy	#60	bcc	lp	ldy	#o_level	lda	depth	sta	[tree],y	cmp	>leaflevel	bcc	notleaf	lda	#1	sta	[tree]	lda	>size	inc	a	sta	>size	bra	goawaynotleaf	lda	#0	sta	[tree]goaway	ret	END